auto;min-height:0}.public-home .product-card+.product-card{margin-left:0}.public-product .product-actions{gap:10px;flex-wrap:wrap}.public-product .product-actions a{font-size:13px;padding-inline:14px}}
</style>

<style scoped>.public-product:has(.public-back){max-width:none;padding:0}.public-back{margin:0 0 24px}.public-product:has(.public-back)>h1{font-size:30px}.public-product:has(.public-back) .product-card{margin-top:20px}</style>
